<!-- @copyBudget 200 Approved V3 overview: metadata, six category entrances and project gallery. -->
<script setup lang="ts">
import { computed, ref } from 'vue'
import BaseIcon from '@/components/ui/BaseIcon.vue'
import { asset } from '@/assets/assets'
import ProjectCover from './ProjectCover.vue'
import { assetRoot, languageLabel, type DataGroup, type DataProject } from './model'
const props=defineProps<{demo:boolean;total:number|null;groups:DataGroup[];projects:DataProject[]|null;projectsError:string;selected:DataProject|null}>()
const emit=defineEmits<{categories:[group:string];project:[project:DataProject,target?:string];select:[project:DataProject];workshop:[project:DataProject];use:[];retry:[]}>()
const filter=ref('all')
const filters=computed(()=>props.demo?[{id:'all',title:'全部',n:4},{id:'submitted',title:'已完成提交',n:2},{id:'draft',title:'继续创作',n:2}]:[{id:'all',title:'全部已保存',n:props.projects?.length??'—'}])
const featured=computed(()=>(props.demo?props.projects?.filter(p=>p.submission_state==='submitted')??[]:props.projects??[]).filter(()=>filter.value!=='draft'))
const drafts=computed(()=>props.demo&&filter.value!=='submitted'?props.projects?.filter(p=>p.submission_state==='draft')??[]:[])
const items=computed(()=>props.groups.flatMap(g=>g.items))
const zeroCount=computed(()=>items.value.some(i=>i.n===null)?'—':items.value.filter(i=>i.n===0).length)
const trace=computed(()=>{
 if(!props.selected)return []
 const code={title:'作品代码',version:props.selected.version,state:'已保存',icon:'document',target:'preview'}
 if(!props.demo)return [code]
 if(props.selected.id==='DEMO-P01')return [{title:'分析表',version:1,state:'已登记',icon:'document',target:'source:DEMO-E01'},code,{title:'测试报告',version:3,state:'已登记',icon:'clipboard',target:'tests'},{title:'我的解释',version:1,state:'已登记',icon:'feedback',target:'source:DEMO-E04'}]
 return [code,{title:'测试记录',version:props.selected.id==='DEMO-P02'?1:0,state:props.selected.id==='DEMO-P02'?'待改进':'尚未提供',icon:'clipboard',target:'tests'}]
})
function show(p:DataProject,target=''){emit('select',p);emit('project',p,target)}
</script>
<template>
 <div class="data-overview">
  <section class="data-summary" aria-label="我的资料概览">
   <div class="summary-content">
    <div class="summary-primary"><img :src="assetRoot+'clipboard.png'" alt="" /><div><span>平台记录</span><strong>{{total??'—'}} <small>条</small></strong><p>{{groups.length}} 大组 · {{items.length}} 个类别 · {{zeroCount}} 个空类别</p></div></div>
    <div class="project-count"><div class="status-ring" :class="{'status-ring--unknown':!demo}" :aria-label="demo?'4个作品，2个已提交，2个创作中':'作品总数，提交状态未提供'"><strong>{{projects?.length??'—'}}</strong></div><div><b>我的作品</b><template v-if="demo"><p><i class="legend-dot" />已提交 2</p><p><i class="legend-dot legend-dot--draft" />创作中 2</p></template><p v-else>仅统计已保存的作品</p></div></div>
    <div class="submission-count"><img :src="assetRoot+'document.png'" alt="" /><div><span>{{demo?'已完成提交':'提交状态'}}</span><strong v-if="demo">2 <small>个</small></strong><p v-else>当前接口未提供</p></div></div>
   </div><p class="summary-note"><BaseIcon name="help-circle" :size="15" />记录不是成绩；完成提交不等于全部达标。</p>
  </section>
  <div class="overview-columns">
   <section class="data-surface category-overview"><h2>全部数据都在这里</h2><div class="group-map"><button v-for="g in groups" :key="g.id" class="group-box" @click="emit('categories',g.id)"><img :src="g.icon" alt="" width="64" height="64" /><span><b>{{g.title}}</b><strong>{{g.count??'—'}} <small>{{g.count===null?'暂未读取':'条'}}</small></strong></span><BaseIcon name="arrow-right" :size="17" /></button></div><div class="category-bottom"><button class="data-button data-button--outline" @click="emit('categories','all')">展开全部 {{items.length}} 类<BaseIcon name="plus" :size="16" /></button><span>含 {{zeroCount}} 个空类别</span></div></section>
   <section class="data-surface project-overview">
    <div class="gallery-heading"><h2>我的作品总览</h2><div class="gallery-filters" role="group" aria-label="筛选作品"><button v-for="f in filters" :key="f.id" :aria-pressed="filter===f.id" :class="{active:filter===f.id}" @click="filter=f.id">{{f.title}} {{f.n}}</button></div></div>
    <div v-if="projectsError" class="project-empty" role="alert"><img :src="assetRoot+'folder.png'" alt="" /><h3>作品暂时没有读到</h3><p>{{projectsError}}</p><button class="data-button data-button--outline" @click="emit('retry')">重新读取作品</button></div>
    <div v-else-if="projects===null" class="project-empty" role="status">正在读取你的作品…</div>
    <div v-else-if="projects.length===0" class="project-empty"><img :src="assetRoot+'folder.png'" alt="" /><h3>还没有保存的作品</h3><p>保存作品后，可以回来查看原件。</p><RouterLink class="data-button data-button--outline" to="/student/ide">去编程工坊</RouterLink></div>
    <template v-else><div v-if="featured.length" class="project-gallery"><article v-for="p in featured" :key="p.id" class="project-card" :class="{'project-card--selected':selected?.id===p.id}">
     <button class="project-preview" :aria-label="'选择'+p.title+'并查看资料链，封面为语言主题插画'" @click="emit('select',p)"><ProjectCover :project="p" /></button>
     <div class="project-title"><h3>{{p.title}}</h3><span class="submitted-label">{{demo?'已完成提交':'已保存'}}</span></div><p class="project-meta">{{p.edit_mode==='blocks'?'图形化 · ':''}}{{languageLabel(p.language)}} · v{{p.version}}</p><div class="project-result"><div><p v-if="demo&&p.tests">测试 {{p.tests.passed}}/{{p.tests.total}} 通过</p><small>{{demo?'教师反馈：待发布':'提交与测试状态未提供'}}</small></div><button class="data-button" @click="show(p)">查看这份作品</button></div>
    </article></div><div v-if="drafts.length" class="draft-list"><h3>继续创作</h3><div v-for="p in drafts" :key="p.id" class="draft-row"><img :src="assetRoot+'document.png'" alt="" /><div><b>{{p.title}}</b><span>{{languageLabel(p.language)}} v{{p.version}} · {{p.next_action}}</span></div><button class="data-button data-button--outline" @click="emit('workshop',p)">{{demo?'查看草稿':'继续'}}</button></div></div></template>
   </section>
  </div>
  <div class="overview-footer"><section class="data-surface evidence-overview"><h2>{{selected?selected.title+'留下了这些资料':'作品的资料从这里回看'}}</h2><div v-if="selected" class="trace-nodes"><button v-for="(node,i) in trace" :key="node.title" class="trace-node" @click="show(selected,node.target)"><img :src="assetRoot+node.icon+'.png'" alt="" /><span><b>{{node.title}}<small v-if="node.version"> v{{node.version}}</small></b><em :class="{'trace-pending':node.state==='待改进'||node.state==='尚未提供'}">{{node.state}}</em></span><span v-if="i<trace.length-1" class="trace-line" aria-hidden="true">→</span></button></div><p v-else class="trace-hint">选择作品，再看版本与原件。</p><div class="trace-bottom"><small>{{demo?'仅当前作品；已登记不代表原文已提供':'未提供任务关联的资料，不自动拼接'}}</small><button v-if="selected" class="data-button data-button--outline" @click="show(selected,'sources')"><BaseIcon name="folder" :size="16" />查看完整资料链</button></div></section><section class="data-surface explanation-overview"><h2>{{demo?'AI 说明 · 演示':'这些记录有什么用'}}</h2><div><img :src="asset('ip_panda_check')" alt="" width="86" height="86" /><div><p>先看作品，再点开它的原件。<br />记录多，不代表能力更强。</p><button class="data-button data-button--outline" @click="emit('use')"><BaseIcon name="help-circle" :size="16" />这些数据有什么用</button></div></div></section></div>
  <p class="data-disclaimer"><BaseIcon name="help-circle" :size="15" />{{demo?'本页数量与作品状态均为演示，不是你的真实学习记录。':'本人资料快照。作品保存、提交、测试与教师评价分别说明。'}}</p>
 </div>
</template>
